// The "long-session" scenario (design D11, phase-1a task 1.1): on the first
// prompt in a session, emits `--items <n>` (default 200) mixed history items
// in one turn, unthrottled, then ends the turn. The content (Markdown answers
// with code and tables, thoughts with bold titles, runs of reads and searches,
// edits with diffs, executes with 20 to 400 lines, one failed call per 50
// items, a plan per 25, the needle 500 items from the end) is generated by
// ../long-session-items.ts. Emission has no sleeps, so it is fast whatever
// --delay-scale is. The same history is the built-in session `long-session`
// that `session/load` (with `--load`) replays, with the load's own pacing
// (agent.ts), so a load can be slowed with --delay-scale. With `--history`
// (mvp-conversation task 1.2) every new session is sent the same history right
// after session/new, before any prompt, and its first prompt gets the short
// reply: the open-at-the-end and budget checks need no turn.
import type { PromptResponse, ToolCallContent } from "@agentclientprotocol/sdk";
import {
  LONG_SESSION_DEFAULT_ITEMS,
  LONG_SESSION_PLAN_EVERY,
  generateLongSessionItems,
  longSessionPlan,
  type LongSessionItem,
  type LongSessionOptions,
} from "../long-session-items.ts";
import type { Scenario, ScenarioContext } from "../scenario.ts";
import type { GeneratedHistory, SendUpdate, StoredSession } from "../sessions.ts";

export { LONG_SESSION_DEFAULT_ITEMS };

async function emitItem(send: SendUpdate, item: LongSessionItem, index: number): Promise<void> {
  switch (item.kind) {
    case "user":
      await send({
        sessionUpdate: "user_message_chunk",
        messageId: `long-user-${index}`,
        content: { type: "text", text: item.text },
      });
      return;
    case "answer":
      await send({
        sessionUpdate: "agent_message_chunk",
        messageId: `long-msg-${index}`,
        content: { type: "text", text: item.text },
      });
      return;
    case "thought":
      await send({
        sessionUpdate: "agent_thought_chunk",
        messageId: `long-thought-${index}`,
        content: { type: "text", text: item.text },
      });
      return;
    case "tool": {
      const toolCallId = `long-tool-${index}`;
      await send({
        sessionUpdate: "tool_call",
        toolCallId,
        title: item.title,
        kind: item.toolKind,
        status: "in_progress",
        ...(item.path ? { locations: [{ path: `/work/${item.path}` }] } : {}),
      });
      const content: ToolCallContent[] = item.diff
        ? [{ type: "diff", path: `/work/${item.path}`, oldText: item.diff.oldText, newText: item.diff.newText }]
        : [{ type: "content", content: { type: "text", text: item.output ?? "" } }];
      await send({
        sessionUpdate: "tool_call_update",
        toolCallId,
        status: item.failed ? "failed" : "completed",
        content,
      });
      return;
    }
  }
}

/**
 * Emits the whole history (`count` items, a plan update after every 25) through
 * `send`; false if `cancelled` aborted it part-way. The first prompt and
 * `session/load` of the built-in session both use it, so they send identical
 * updates (8303 at 5000 items).
 */
async function emitHistory(send: SendUpdate, count: number, options: LongSessionOptions, cancelled?: AbortSignal): Promise<boolean> {
  let index = 0;
  for (const item of generateLongSessionItems(count, options)) {
    await emitItem(send, item, index);
    index += 1;
    if (index % LONG_SESSION_PLAN_EVERY === 0) {
      await send({ sessionUpdate: "plan", entries: longSessionPlan(index / LONG_SESSION_PLAN_EVERY) });
    }
    if (cancelled?.aborted) {
      return false;
    }
  }
  return true;
}

/** The history as a session holds it: replayed by `session/load` and sent by `--history`. */
function generatedHistory(items: number, options: LongSessionOptions): GeneratedHistory {
  return { turnCount: 1, replay: (send) => emitHistory(send, items, options).then(() => undefined) };
}

/**
 * The ID of the session `session/load` (with `--load`) replays the history of;
 * it is also listed by `session/list` (with `--list`) under the fake agent's
 * working directory.
 */
export const LONG_SESSION_SESSION_ID = "long-session";

/** Fixed, so a list of the built-in session is byte-identical between runs. */
export const LONG_SESSION_UPDATED_AT = "2026-10-01T12:00:00.000Z";

/** Prompts answered so far, per session (a scenario instance serves one agent process). */
const promptsSeen = new Map<string, number>();

function makeLongSessionScenario(name: string, options: LongSessionOptions): Scenario {
  return {
    name,

    builtinSessions(items: number): readonly StoredSession[] {
      return [
        {
          sessionId: LONG_SESSION_SESSION_ID,
          cwd: process.cwd(),
          title: `Long session (${items} items)`,
          updatedAt: LONG_SESSION_UPDATED_AT,
          turns: [],
          generated: generatedHistory(items, options),
        },
      ];
    },

    history: (items: number) => generatedHistory(items, options),

    sessionLoaded(sessionId: string, turns: number): void {
      // A loaded history counts as answered prompts, so the next prompt gets the
      // short reply and never repeats the history.
      promptsSeen.set(sessionId, Math.max(promptsSeen.get(sessionId) ?? 0, turns));
    },

    async prompt(ctx: ScenarioContext): Promise<PromptResponse> {
      const turn = (promptsSeen.get(ctx.sessionId) ?? 0) + 1;
      promptsSeen.set(ctx.sessionId, turn);
      if (turn > 1) {
        // Later prompts get one short, ordinary reply with a fresh message ID, so
        // the history is never re-emitted (same IDs would merge into old items).
        await ctx.send({
          sessionUpdate: "agent_message_chunk",
          messageId: `long-reply-${turn}`,
          content: { type: "text", text: `Reply ${turn}: the earlier history is unchanged.` },
        });
        return { stopReason: "end_turn" };
      }
      const finished = await emitHistory((update) => ctx.send(update), ctx.items, options, ctx.cancelled);
      return { stopReason: finished ? "end_turn" : "cancelled" };
    },
  };
}

export const longSessionScenario: Scenario = makeLongSessionScenario("long-session", {});

/**
 * `long-session` with every tool output sent unfenced, as agents other than `claude-agent-acp`
 * may send it (acp-tui's tui-find "Search cost": the first search over Markdown-rendered tool
 * text). Everything else, the built-in session and `--history` included, is the same.
 */
export const longSessionPlainScenario: Scenario = makeLongSessionScenario("long-session-plain", { fenced: false });
